//! Conservative sequential M1 memory (§6.9).
//!
//! Reference IDs name concrete SSA addresses, not points-to abstractions. Cloning
//! a state is only appropriate for snapshots; exploration branches use `fork`.
//!
//! Integration contract: the engine owns diagnostics, run assumptions, and
//! address interning. In particular, reexecuting an ALLOC instruction requires a
//! fresh reference ID as well as the activation generated by `allocate`.
use std::collections::{BTreeMap, BTreeSet};

/// Adapter to the expression arena. `fresh` must allocate a genuinely fresh
/// symbol; `ite` must preserve both branches unless its guard is proven.
pub trait MemoryBackend {
    type Expr: Clone + Eq;
    type Sort: Clone + Eq;
    fn sort(&self, expr: &Self::Expr) -> Self::Sort;
    fn fresh(&mut self, sort: &Self::Sort, hint: &str) -> Self::Expr;
    fn fresh_bool(&mut self, hint: &str) -> Self::Expr;
    fn ite(&mut self, guard: Self::Expr, yes: Self::Expr, no: Self::Expr) -> Self::Expr;
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub struct Activation {
    pub lineage: Vec<u64>,
    pub counter: u64,
}

#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
pub enum Loc {
    AllocationSite(u64),
    AllocInstance(u64, Activation),
    AllocSummary(u64, String),
    ParamPointee(String, u32),
    Global(String),
    FieldOf(Box<Loc>, u32),
    Unknown,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum Precision {
    MustSingleton,
    MaySet,
    Unknown,
}

/// Assigned by the engine from SSA address identity. Proven-equal addresses
/// must reuse this ID; merely sharing a points-to summary does not suffice.
pub type ReferenceId = u64;

#[derive(Clone, Debug)]
pub struct Pointer {
    pub reference: ReferenceId,
    pub targets: BTreeSet<Loc>,
    pub precision: Precision,
}

impl Pointer {
    pub fn new(
        reference: ReferenceId,
        targets: impl IntoIterator<Item = Loc>,
        precision: Precision,
    ) -> Self {
        Self {
            reference,
            targets: targets.into_iter().collect(),
            precision,
        }
    }

    /// The engine interns `(parent address, field index)` as an address identity.
    pub fn field(&self, reference: ReferenceId, index: u32) -> Self {
        Self::new(
            reference,
            self.targets
                .iter()
                .cloned()
                .map(|parent| Loc::FieldOf(Box::new(parent), index)),
            self.precision,
        )
    }

    fn unbounded(&self) -> bool {
        self.precision == Precision::Unknown
            || self.targets.is_empty()
            || self
                .targets
                .iter()
                .any(|l| matches!(root(l), Loc::Unknown | Loc::AllocationSite(_)))
    }
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub enum StoreEffect {
    Strong,
    Weak,
    /// Caller must emit a diagnostic and degrade soundness.
    Havoc,
}

#[derive(Clone)]
struct Write<E> {
    pointer: Pointer,
    value: E,
}

pub struct MemoryState<B: MemoryBackend> {
    pub epoch: u64,
    lineage: Vec<u64>,
    allocation_counter: u64,
    fork_counter: u64,
    escaped: BTreeSet<Loc>,
    map: BTreeMap<Loc, B::Expr>,
    initial: BTreeMap<ReferenceId, (Pointer, B::Sort, B::Expr)>,
    store_log: Vec<Write<B::Expr>>,
    aliases: BTreeMap<(ReferenceId, ReferenceId), B::Expr>,
    reinterpreted: BTreeMap<(ReferenceId, usize), B::Expr>,
}

impl<B: MemoryBackend> Clone for MemoryState<B> {
    fn clone(&self) -> Self {
        Self {
            epoch: self.epoch,
            lineage: self.lineage.clone(),
            allocation_counter: self.allocation_counter,
            fork_counter: self.fork_counter,
            escaped: self.escaped.clone(),
            map: self.map.clone(),
            initial: self.initial.clone(),
            store_log: self.store_log.clone(),
            aliases: self.aliases.clone(),
            reinterpreted: self.reinterpreted.clone(),
        }
    }
}

impl<B: MemoryBackend> Default for MemoryState<B> {
    fn default() -> Self {
        Self {
            epoch: 0,
            lineage: vec![],
            allocation_counter: 0,
            fork_counter: 0,
            escaped: BTreeSet::new(),
            map: BTreeMap::new(),
            initial: BTreeMap::new(),
            store_log: vec![],
            aliases: BTreeMap::new(),
            reinterpreted: BTreeMap::new(),
        }
    }
}

impl<B: MemoryBackend> MemoryState<B> {
    /// Initial global reads, before writes are overlaid. Summary substitution
    /// must never mistake a stored parameter for the initial global symbol.
    pub fn summary_global_reads(&self) -> Vec<(String, B::Expr)> {
        self.initial
            .values()
            .filter_map(|(pointer, _, expression)| {
                if pointer.targets.len() != 1 {
                    return None;
                }
                if let Some(Loc::Global(global)) = pointer.targets.iter().next() {
                    Some((global.clone(), expression.clone()))
                } else {
                    None
                }
            })
            .collect()
    }

    /// Last known value written to each global location. Any other write is
    /// retained as Unknown, so callers cannot silently assume memory purity.
    pub fn summary_delta(&self) -> Vec<(Loc, B::Expr)> {
        let mut writes = BTreeMap::new();
        for write in &self.store_log {
            let location = if write.pointer.targets.len() == 1 {
                match write.pointer.targets.iter().next() {
                    Some(Loc::Global(global)) => Loc::Global(global.clone()),
                    _ => Loc::Unknown,
                }
            } else {
                Loc::Unknown
            };
            writes.insert(location, write.value.clone());
        }
        writes.into_iter().collect()
    }

    /// Both children receive unique future activation namespaces. Existing
    /// allocation identities are preserved. Repeated forks of the parent are safe.
    pub fn fork(&mut self) -> (Self, Self) {
        let generation = self.fork_counter;
        self.fork_counter = self
            .fork_counter
            .checked_add(1)
            .expect("fork counter overflow");
        let copy = |side| Self {
            epoch: self.epoch,
            lineage: [self.lineage.clone(), vec![generation, side]].concat(),
            allocation_counter: self.allocation_counter,
            fork_counter: 0,
            escaped: self.escaped.clone(),
            map: self.map.clone(),
            initial: self.initial.clone(),
            store_log: self.store_log.clone(),
            aliases: self.aliases.clone(),
            reinterpreted: self.reinterpreted.clone(),
        };
        (copy(0), copy(1))
    }

    pub fn allocate(&mut self, site: u64, reference: ReferenceId) -> Pointer {
        self.allocation_counter = self
            .allocation_counter
            .checked_add(1)
            .expect("allocation counter overflow");
        Pointer::new(
            reference,
            [Loc::AllocInstance(
                site,
                Activation {
                    lineage: self.lineage.clone(),
                    counter: self.allocation_counter,
                },
            )],
            Precision::MustSingleton,
        )
    }

    pub fn mark_escaped(&mut self, pointer: &Pointer) {
        for loc in &pointer.targets {
            self.escaped.insert(root(loc).clone());
        }
    }

    fn strong(&self, p: &Pointer) -> bool {
        p.precision == Precision::MustSingleton
            && p.targets.len() == 1
            && p.targets.iter().all(|l| {
                matches!(root(l), Loc::AllocInstance(..) | Loc::Global(_))
                    && !self.escaped.contains(root(l))
            })
    }

    fn disjoint(&self, a: &Pointer, b: &Pointer) -> bool {
        !a.targets.is_empty()
            && !b.targets.is_empty()
            && a.targets.iter().all(|x| {
                b.targets.iter().all(|y| {
                    let (x, y) = (root(x), root(y));
                    let fresh =
                        |l: &Loc| matches!(l, Loc::AllocInstance(..)) && !self.escaped.contains(l);
                    // Summaries are deliberately never separated from instances.
                    !matches!(
                        x,
                        Loc::AllocSummary(..) | Loc::Unknown | Loc::AllocationSite(_)
                    ) && !matches!(
                        y,
                        Loc::AllocSummary(..) | Loc::Unknown | Loc::AllocationSite(_)
                    ) && x != y
                        && (fresh(x) || fresh(y))
                })
            })
    }

    fn overlay(
        &mut self,
        backend: &mut B,
        read: &Pointer,
        write: &Pointer,
        yes: B::Expr,
        no: B::Expr,
    ) -> B::Expr {
        if read.reference == write.reference {
            return yes;
        }
        if self.disjoint(read, write) {
            return no;
        }
        let key = (
            read.reference.min(write.reference),
            read.reference.max(write.reference),
        );
        let guard = self
            .aliases
            .entry(key)
            .or_insert_with(|| backend.fresh_bool("memory_alias"))
            .clone();
        // No mutual-exclusion or transitivity assumptions on possible aliases:
        // every real address-equality assignment remains admitted.
        backend.ite(guard, yes, no)
    }

    /// Unknown targets are explicitly overapproximated; caller degrades soundness.
    /// Reads still reconstruct through the write log: a re-read of the *same
    /// SSA reference* must return the stored value even when the target is
    /// unknown (§6.9), while other references keep conservative alias guards.
    pub fn load(&mut self, backend: &mut B, pointer: &Pointer, sort: &B::Sort) -> B::Expr {
        let mut value = if pointer.unbounded() {
            backend.fresh(sort, "unknown_load")
        } else if let Some((_, old_sort, value)) = self.initial.get(&pointer.reference) {
            if old_sort == sort {
                value.clone()
            } else {
                // Same SSA address reloaded through a different type (BITCAST,
                // union, partial aggregate): never panic; reinterpreted bytes are
                // an overapproximation, so read a fresh typed unknown.
                backend.fresh(sort, "reinterpreted_load")
            }
        } else {
            let mut value =
                backend.fresh(sort, &format!("init:{:?}@{}", pointer.targets, self.epoch));
            // Initial reads must also agree under possible address equality.
            let earlier: Vec<_> = self.initial.values().cloned().collect();
            for (other, other_sort, old) in earlier {
                if other_sort == *sort {
                    value = self.overlay(backend, pointer, &other, old, value);
                }
            }
            self.initial.insert(
                pointer.reference,
                (pointer.clone(), sort.clone(), value.clone()),
            );
            value
        };
        for (index, write) in self.store_log.clone().into_iter().enumerate() {
            let written = if backend.sort(&write.value) == *sort {
                write.value
            } else {
                // Partial aggregate / overlapping differently typed access:
                // forget the written bytes rather than build an ill-typed ITE.
                self.reinterpreted
                    .entry((pointer.reference, index))
                    .or_insert_with(|| backend.fresh(sort, "partial_memory_write"))
                    .clone()
            };
            value = self.overlay(backend, pointer, &write.pointer, written, value);
        }
        value
    }

    pub fn store(&mut self, pointer: &Pointer, value: B::Expr) -> StoreEffect {
        if pointer.unbounded() {
            // Explicitly overapproximate the other memories, but preserve the
            // write itself: a later read of the same SSA reference must return
            // it, even though its target is not known (§6.9).
            self.havoc_all_memory();
            self.store_log.push(Write {
                pointer: pointer.clone(),
                value,
            });
            return StoreEffect::Havoc;
        }
        let effect = if self.strong(pointer) {
            self.map.insert(
                pointer.targets.iter().next().unwrap().clone(),
                value.clone(),
            );
            StoreEffect::Strong
        } else {
            StoreEffect::Weak
        };
        // Even weak stores are exact when reread through the same SSA address.
        self.store_log.push(Write {
            pointer: pointer.clone(),
            value,
        });
        effect
    }

    pub fn havoc_all_memory(&mut self) {
        self.epoch = self.epoch.checked_add(1).expect("memory epoch overflow");
        self.map.clear();
        self.initial.clear();
        self.store_log.clear();
        self.aliases.clear();
        self.reinterpreted.clear();
    }
}

fn root(loc: &Loc) -> &Loc {
    match loc {
        Loc::FieldOf(parent, _) => root(parent),
        _ => loc,
    }
}

#[cfg(test)]
mod tests {
    use super::*;

    // An independent evaluable expression tree, not an arena implementation.
    #[derive(Clone, Debug, PartialEq, Eq)]
    enum E {
        Val(i64),
        Var(usize),
        Ite(Box<E>, Box<E>, Box<E>),
    }
    #[derive(Default)]
    struct Backend {
        next: usize,
    }
    impl MemoryBackend for Backend {
        type Expr = E;
        type Sort = ();
        fn sort(&self, _: &E) {}
        fn fresh(&mut self, _: &(), _: &str) -> E {
            let id = self.next;
            self.next += 1;
            E::Var(id)
        }
        fn fresh_bool(&mut self, hint: &str) -> E {
            self.fresh(&(), hint)
        }
        fn ite(&mut self, guard: E, yes: E, no: E) -> E {
            if yes == no {
                yes
            } else {
                E::Ite(Box::new(guard), Box::new(yes), Box::new(no))
            }
        }
    }
    fn param(id: u64) -> Pointer {
        Pointer::new(
            id,
            [Loc::ParamPointee("f".into(), id as u32)],
            Precision::MaySet,
        )
    }
    fn eval(e: &E, vars: &BTreeMap<usize, i64>) -> i64 {
        match e {
            E::Val(v) => *v,
            E::Var(i) => vars.get(i).copied().unwrap_or(0),
            E::Ite(c, a, b) => eval(if eval(c, vars) != 0 { a } else { b }, vars),
        }
    }
    fn alias_assignment(m: &MemoryState<Backend>, addresses: &[u64]) -> BTreeMap<usize, i64> {
        m.aliases
            .iter()
            .map(|(&(a, b), e)| {
                let E::Var(id) = e else {
                    panic!("alias must be free")
                };
                (
                    *id,
                    i64::from(addresses[a as usize] == addresses[b as usize]),
                )
            })
            .collect()
    }

    #[test]
    fn memory_two_loads_same_expr() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let p = param(0);
        assert_eq!(m.load(&mut b, &p, &()), m.load(&mut b, &p, &()));
        assert_eq!(m.store(&p, E::Val(42)), StoreEffect::Weak);
        assert_eq!(m.load(&mut b, &p, &()), E::Val(42));
        let q = param(1);
        m.store(&q, E::Val(7));
        assert_eq!(m.load(&mut b, &p, &()), m.load(&mut b, &p, &()));
    }
    #[test]
    fn memory_strong_update() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let p = m.allocate(4, 0);
        assert_eq!(m.store(&p, E::Val(1)), StoreEffect::Strong);
        assert_eq!(m.load(&mut b, &p, &()), E::Val(1));
        let field = p.field(2, 0);
        assert_eq!(m.store(&field, E::Val(8)), StoreEffect::Strong);
        assert_eq!(m.load(&mut b, &field, &()), E::Val(8));
        m.mark_escaped(&p);
        assert_eq!(m.store(&p, E::Val(2)), StoreEffect::Weak);
        assert_eq!(m.store(&field, E::Val(4)), StoreEffect::Weak);
        let mut imprecise = p.clone();
        imprecise.precision = Precision::MaySet;
        assert_eq!(m.store(&imprecise, E::Val(3)), StoreEffect::Weak);
    }
    #[test]
    fn memory_alias_param_param() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let (p, q) = (param(0), param(1));
        m.store(&p, E::Val(11));
        let read = m.load(&mut b, &q, &());
        assert_eq!(eval(&read, &alias_assignment(&m, &[0, 0])), 11);
        assert_ne!(eval(&read, &alias_assignment(&m, &[0, 1])), 11);
        assert_eq!(m.load(&mut b, &p, &()), E::Val(11));
    }
    #[test]
    fn memory_alloc_distinct() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let (p, q) = (m.allocate(1, 0), m.allocate(2, 1));
        m.store(&p, E::Val(3));
        m.store(&q, E::Val(4));
        assert_eq!(m.load(&mut b, &p, &()), E::Val(3));
        assert_eq!(m.load(&mut b, &q, &()), E::Val(4));
        let r = param(2);
        m.store(&r, E::Val(8));
        assert_eq!(m.load(&mut b, &p, &()), E::Val(3));
        m.mark_escaped(&p);
        assert!(!m.disjoint(&p, &r));
    }
    #[test]
    fn memory_havoc_epoch() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let p = param(0);
        let first = m.load(&mut b, &p, &());
        m.store(&p, E::Val(5));
        m.havoc_all_memory();
        assert_eq!(m.epoch, 1);
        let next = m.load(&mut b, &p, &());
        assert_ne!(first, next);
        assert_ne!(next, E::Val(5));
        assert_eq!(next, m.load(&mut b, &p, &()));
        assert_eq!(
            m.store(
                &Pointer::new(99, [Loc::Unknown], Precision::Unknown),
                E::Val(2)
            ),
            StoreEffect::Havoc
        );
        assert_eq!(m.epoch, 2);
        let unknown_field = Pointer::new(100, [Loc::Unknown], Precision::MaySet).field(101, 0);
        assert_eq!(m.store(&unknown_field, E::Val(2)), StoreEffect::Havoc);
        assert_eq!(m.epoch, 3);
    }
    #[test]
    fn memory_same_site_two_iterations() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let (p, q) = (m.allocate(1, 0), m.allocate(1, 1));
        assert_ne!(p.targets, q.targets);
        m.store(&p, E::Val(1));
        m.store(&q, E::Val(2));
        assert_eq!(m.load(&mut b, &p, &()), E::Val(1));
        let (mut a, mut c) = m.fork();
        let (mut d, _) = m.fork();
        let ap = a.allocate(1, 2);
        let cp = c.allocate(1, 2);
        let dp = d.allocate(1, 2);
        assert_ne!(ap.targets, cp.targets);
        assert_ne!(ap.targets, dp.targets);
        assert_eq!(a.load(&mut b, &p, &()), E::Val(1));
        assert_eq!(c.load(&mut b, &p, &()), E::Val(1));
    }
    #[test]
    fn memory_summary_never_strong_update() {
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let p = m.allocate(1, 0);
        let s = Pointer::new(
            1,
            [Loc::AllocSummary(1, "loop".into())],
            Precision::MustSingleton,
        );
        m.store(&p, E::Val(1));
        assert_eq!(m.store(&s, E::Val(9)), StoreEffect::Weak);
        assert!(!m.disjoint(&p, &s));
        let read = m.load(&mut b, &p, &());
        assert_eq!(eval(&read, &alias_assignment(&m, &[0, 0])), 9);
        assert_eq!(eval(&read, &alias_assignment(&m, &[0, 1])), 1);
    }
    #[test]
    fn memory_same_reference_visible_under_unknown_store() {
        // §6.9: a store through an unknown target still leaves the write visible
        // to a later load through the exact same SSA reference, while other
        // references only see it under a conservative alias guard.
        let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
        let unknown = Pointer::new(0, [Loc::Unknown], Precision::Unknown);
        m.store(&unknown, E::Val(9));
        assert_eq!(m.load(&mut b, &unknown, &()), E::Val(9));
        let other = param(1);
        let read = m.load(&mut b, &other, &());
        assert_eq!(eval(&read, &alias_assignment(&m, &[0, 0])), 9);
        assert_ne!(eval(&read, &alias_assignment(&m, &[0, 1])), 9);
    }
    #[derive(Clone, Debug, PartialEq, Eq)]
    enum T {
        Word,
        Byte,
    }
    #[derive(Clone, Debug, PartialEq, Eq)]
    enum TE {
        Tag(usize, T),
    }
    struct Tagged;
    impl MemoryBackend for Tagged {
        type Expr = TE;
        type Sort = T;
        fn sort(&self, e: &TE) -> T {
            match e {
                TE::Tag(_, t) => t.clone(),
            }
        }
        fn fresh(&mut self, sort: &T, _hint: &str) -> TE {
            TE::Tag(0, sort.clone())
        }
        fn fresh_bool(&mut self, _hint: &str) -> TE {
            TE::Tag(0, T::Byte)
        }
        fn ite(&mut self, _g: TE, yes: TE, no: TE) -> TE {
            if yes == no {
                yes
            } else {
                TE::Tag(1, self.sort(&yes))
            }
        }
    }
    #[test]
    fn memory_type_mismatch_reload_never_panics() {
        // Same SSA reference loaded through two types must never panic (the
        // old assert left the run RUNNING); reinterpreted bytes are a fresh
        // overapproximated unknown for the requested sort.
        let (mut m, mut b) = (MemoryState::<Tagged>::default(), Tagged);
        let p = param(0);
        let word = m.load(&mut b, &p, &T::Word);
        let byte = m.load(&mut b, &p, &T::Byte);
        assert_ne!(word, byte);
        assert_eq!(byte, m.load(&mut b, &p, &T::Byte));
    }
    #[test]
    fn memory_alias_chain_soundness() {
        // Exhaust all concrete address assignments for three parameters and
        // compare ordered writes/reads against a concrete heap oracle. This
        // includes p=q=r, p=r!=q, p=q!=r, q=r!=p, and all-distinct.
        for a in 0..3 {
            for c in 0..3 {
                for d in 0..3 {
                    let addresses = [a, c, d];
                    let (mut m, mut b) = (MemoryState::<Backend>::default(), Backend::default());
                    let pointers = [param(0), param(1), param(2)];
                    let mut heap = BTreeMap::new();
                    for (i, p) in pointers.iter().enumerate() {
                        let value = (i as i64 + 1) * 10;
                        heap.insert(addresses[i], value);
                        m.store(p, E::Val(value));
                        for (j, q) in pointers.iter().enumerate() {
                            let read = m.load(&mut b, q, &());
                            if let Some(expected) = heap.get(&addresses[j]) {
                                assert_eq!(
                                    eval(&read, &alias_assignment(&m, &addresses)),
                                    *expected,
                                    "addresses={addresses:?}, write={i}, read={j}"
                                );
                            }
                        }
                    }
                    assert_eq!(m.aliases.len(), 3);
                }
            }
        }
    }
}
